<#
.DESCRIPTION
Checks which of 40 silent Windows failure modes for Claude Code and Codex CLI reproduce on this PC.
#>

# build.py embeds the check scripts, titles and messages in docs/doctor.ps1.
& {
    if ($PSVersionTable.PSEdition -ne 'Desktop' -or $PSVersionTable.PSVersion -lt [version]'5.1' -or
        [Environment]::OSVersion.Platform -ne [PlatformID]::Win32NT) { return }

    $traps = @'
[
{"id": "t01", "ja": "PowerShell \u306e\u7d42\u4e86\u30b3\u30fc\u30c9\u304c\u30012 \u3092\u8fd4\u3057\u305f\u306e\u306b 1 \u306b\u306a\u308b", "en": "PowerShell returns exit code 1 when the script exited with 2", "claude": false, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\n[IO.File]::WriteAllText(\"$d\\exit2.ps1\", 'exit 2')\r\npowershell -NoProfile -ExecutionPolicy Bypass -File \"$d\\exit2.ps1\"; $a = $LASTEXITCODE\r\npowershell -NoProfile -ExecutionPolicy Bypass -Command \"& '$d\\exit2.ps1'\"; $b = $LASTEXITCODE\r\n\"-File=$a  -Command=$b\"\r\nif ($a -eq 2 -and $b -eq 1) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "t02", "ja": "-File \u3067\u6e21\u3057\u305f2\u3064\u76ee\u306e\u5f15\u6570\u304c\u3001\u30a8\u30e9\u30fc\u306a\u3057\u3067\u6d88\u3048\u308b", "en": "The second value passed with -File disappears without an error", "claude": false, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\n[IO.File]::WriteAllText(\"$d\\arr.ps1\", 'param([string[]]$Path) \"count=$($Path.Count) first=$($Path[0])\"')\r\n$o = powershell -NoProfile -ExecutionPolicy Bypass -File \"$d\\arr.ps1\" -Path a b; $e = $LASTEXITCODE\r\n\"$o  exit=$e\"\r\nif ($o -eq 'count=1 first=a' -and $e -eq 0) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "t03", "ja": "-File \u3067 a,b \u3068\u6e21\u3059\u3068\u3001\u914d\u5217\u306b\u306a\u3089\u305a1\u3064\u306e\u6587\u5b57\u5217\u306b\u306a\u308b", "en": "With -File, a,b stays one string instead of an array", "claude": false, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\n[IO.File]::WriteAllText(\"$d\\arr.ps1\", 'param([string[]]$Path) \"count=$($Path.Count) first=$($Path[0])\"')\r\n$o = powershell -NoProfile -ExecutionPolicy Bypass -File \"$d\\arr.ps1\" -Path a,b\r\n$o\r\nif ($o -eq 'count=1 first=a,b') { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "t04", "ja": "\u30d1\u30a4\u30d7\u3067\u6e21\u3057\u305f\u65e5\u672c\u8a9e\u304c ? \u306b\u306a\u308b\uff08claude -p\u30fbpython\u30fbgit\uff09", "en": "Non-ASCII text piped to claude -p, python or git arrives as ?", "claude": false, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\n$pyv = & python -c \"import sys; print('%d.%d.%d' % sys.version_info[:3])\" 2>$null\r\nif (-not $pyv) { 'CANNOT CHECK (python not found, or only the Microsoft Store stub: install Python from python.org)' } else {\r\n\"python $pyv\"\r\n[IO.File]::WriteAllText(\"$d\\hex.py\", 'import sys; print(sys.stdin.buffer.read().strip().hex())')\r\n$s = [string][char]0x65E5 + [char]0x672C\r\n$h = $s | python \"$d\\hex.py\"\r\n\"bytes=$h  (UTF-8 would be e697a5e69cac)\"\r\nif ($h -match '^(efbbbf)?(3f)+$') { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n}\r\n"},
{"id": "t05", "ja": "python \u3084 claude \u306e\u51fa\u529b\u3092\u5909\u6570\u306b\u5165\u308c\u308b\u3068\u6587\u5b57\u5316\u3051\u3059\u308b", "en": "Output from python or claude turns into mojibake in a variable", "claude": false, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\n$pyv = & python -c \"import sys; print('%d.%d.%d' % sys.version_info[:3])\" 2>$null\r\nif (-not $pyv) { 'CANNOT CHECK (python not found, or only the Microsoft Store stub: install Python from python.org)' } else {\r\n\"python $pyv\"\r\n[IO.File]::WriteAllText(\"$d\\say.py\", 'import sys; sys.stdout.buffer.write((chr(0x65e5)+chr(0x672c)).encode(\"utf-8\"))')\r\n$s = python \"$d\\say.py\"\r\n$want = [string][char]0x65E5 + [char]0x672C\r\n\"read with code page $([Console]::OutputEncoding.CodePage): \" + (($s.ToCharArray() | ForEach-Object { '{0:X4}' -f [int]$_ }) -join ' ') + '  (want 65E5 672C)'\r\nif ($s -ne $want) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n}\r\n"},
{"id": "t06", "ja": "\u624b\u3067\u52d5\u304b\u3059\u3068\u901a\u308b Python \u304c\u3001\u30bf\u30b9\u30af\u30b9\u30b1\u30b8\u30e5\u30fc\u30e9\u3084\u30ea\u30c0\u30a4\u30ec\u30af\u30c8\u306e\u3068\u304d\u3060\u3051\u843d\u3061\u308b", "en": "Python works when run by hand but crashes under Task Scheduler or redirection", "claude": false, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\n$pyv = & python -c \"import sys; print('%d.%d.%d' % sys.version_info[:3])\" 2>$null\r\nif (-not $pyv) { 'CANNOT CHECK (python not found, or only the Microsoft Store stub: install Python from python.org)' } else {\r\n\"python $pyv\"\r\n[IO.File]::WriteAllText(\"$d\\dash.py\", 'print(\"a\" + chr(0x2014) + chr(0x2713) + \"b\")')\r\npython \"$d\\dash.py\" > \"$d\\out.txt\" 2> \"$d\\err.txt\"; $e = $LASTEXITCODE\r\n$err = [IO.File]::ReadAllText(\"$d\\err.txt\")\r\n\"exit=$e, UnicodeEncodeError=$($err -match 'UnicodeEncodeError')\"\r\nif ($e -ne 0 -and $err -match 'UnicodeEncodeError') { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n}\r\n"},
{"id": "t07", "ja": "PYTHONIOENCODING \u3092\u8a2d\u5b9a\u3057\u305f\u306e\u306b\u3001python -I \u3060\u3068\u52b9\u304b\u306a\u3044", "en": "PYTHONIOENCODING is set, but python -I ignores it", "claude": false, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\n$pyv = & python -c \"import sys; print('%d.%d.%d' % sys.version_info[:3])\" 2>$null\r\nif (-not $pyv) { 'CANNOT CHECK (python not found, or only the Microsoft Store stub: install Python from python.org)' } else {\r\n\"python $pyv\"\r\n[IO.File]::WriteAllText(\"$d\\dash.py\", 'print(\"a\" + chr(0x2014) + chr(0x2713) + \"b\")')\r\n$old = $env:PYTHONIOENCODING; $env:PYTHONIOENCODING = 'utf-8'\r\npython -I \"$d\\dash.py\" > \"$d\\o1.txt\" 2> \"$d\\e1.txt\"; $a = $LASTEXITCODE\r\npython \"$d\\dash.py\" > \"$d\\o2.txt\" 2> \"$d\\e2.txt\"; $b = $LASTEXITCODE\r\n$env:PYTHONIOENCODING = $old\r\n$err = [IO.File]::ReadAllText(\"$d\\e1.txt\")\r\n\"with -I exit=$a, without -I exit=$b\"\r\nif ($a -ne 0 -and $err -match 'UnicodeEncodeError' -and $b -eq 0) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n}\r\n"},
{"id": "t08", "ja": "\u65e5\u672c\u8a9e\u5165\u308a\u306e .ps1 \u304c\u3001\u69cb\u6587\u30a8\u30e9\u30fc\u306b\u306a\u308b\u304b\u6587\u5b57\u5316\u3051\u3057\u3066\u52d5\u304f", "en": "A .ps1 with non-ASCII text fails to parse or prints mojibake", "claude": false, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\n$want = [string][char]0x65E5 + [char]0x672C\r\n[IO.File]::WriteAllText(\"$d\\nobom.ps1\", \"Write-Output '$want'\", (New-Object System.Text.UTF8Encoding $false))\r\n$o = powershell -NoProfile -ExecutionPolicy Bypass -File \"$d\\nobom.ps1\"\r\n\"got $o (want $want)\"\r\nif ($o -ne $want) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "t09", "ja": ".cmd / .bat \u306e\u30b3\u30e1\u30f3\u30c8\u304c\u3001\u30b3\u30de\u30f3\u30c9\u3068\u3057\u3066\u5b9f\u884c\u3055\u308c\u308b", "en": "A .cmd / .bat file runs its comment text as commands", "claude": false, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\n$k = [string][char]0x65E5 + [char]0x672C\r\n[IO.File]::WriteAllText(\"$d\\lf.cmd\", \"@echo off`nrem $k$k$k comment`nrem $k more`necho START`necho END`n\", [Text.Encoding]::GetEncoding(932))\r\n$o = cmd /c \"`\"$d\\lf.cmd`\" 2>&1\" | Out-String; $e = $LASTEXITCODE\r\n$extra = @($o -split \"`r?`n\" | Where-Object { $_.Trim() -ne '' -and $_.Trim() -ne 'START' -and $_.Trim() -ne 'END' })\r\n$o; \"console code page $([Console]::OutputEncoding.CodePage), exit=$e, unexpected lines=$($extra.Count)\"\r\nif ($e -ne 0 -or $o -notmatch 'START' -or $extra.Count -gt 0) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "t10", "ja": "powershell -Command \u306e1\u884c\u306b\u66f8\u3044\u305f $\u5909\u6570 \u304c\u3001\u547c\u3076\u524d\u306b\u6d88\u3048\u308b", "en": "$variables in a powershell -Command one-liner vanish before it runs", "claude": false, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\npowershell -NoProfile -Command \"foreach ($i in 1..2) { $i }\"; $e = $LASTEXITCODE\r\n\"exit=$e\"\r\nif ($e -ne 0) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "t11", "ja": "Get-ChildItem \u306e -Include \u304c\u52b9\u304b\u305a\u3001\u5168\u90e8\u306e\u30d5\u30a1\u30a4\u30eb\u304c\u8fd4\u308b", "en": "Get-ChildItem -Include is ignored and every file comes back", "claude": false, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\nNew-Item -ItemType Directory \"$d\\inc\" -Force | Out-Null\r\n[IO.File]::WriteAllText(\"$d\\inc\\a.ps1\", 'x'); [IO.File]::WriteAllText(\"$d\\inc\\b.md\", 'x')\r\n$n = @(Get-ChildItem -LiteralPath \"$d\\inc\" -Recurse -File -Include *.ps1).Count\r\n\"matched $n files for -Include *.ps1 (expected 1)\"\r\nif ($n -eq 2) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "t12", "ja": "\"...\" \u306b\u66f8\u3044\u305f Markdown \u306e\u30d0\u30c3\u30af\u30af\u30a9\u30fc\u30c8\u3067\u3001\u6587\u5b57\u304c\u6d88\u3048\u3066\u6539\u884c\u304c\u5165\u308b", "en": "Markdown backticks inside \"...\" turn into newlines and tabs", "claude": false, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\n$t = \"use `night-shift and `true.\"\r\n$t\r\nif ($t -match \"`n\" -or $t -match \"`t\") { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "t13", "ja": "\u66f8\u304d\u8fbc\u307f\u4e2d\u306e\u30ed\u30b0\u304c 0 \u30d0\u30a4\u30c8\u306b\u898b\u3048\u308b", "en": "A log that is being written shows 0 bytes", "claude": false, "slow": true, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\n$pyv = & python -c \"import sys; print('%d.%d.%d' % sys.version_info[:3])\" 2>$null\r\nif (-not $pyv) { 'CANNOT CHECK (python not found, or only the Microsoft Store stub: install Python from python.org)' } else {\r\n\"python $pyv\"\r\n$ad = Join-Path $env:LOCALAPPDATA ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $ad -Force | Out-Null\r\n$log = Join-Path $ad 'w.log'; [IO.File]::WriteAllText($log, '')\r\n[IO.File]::WriteAllText(\"$d\\writer.py\", \"import sys,time`nf=open(sys.argv[1],'a')`nf.write('x'*5000000)`nf.flush()`ntime.sleep(20)`nf.close()`n\")\r\n$p = Start-Process python -ArgumentList \"`\"$d\\writer.py`\"\", \"`\"$log`\"\" -PassThru -WindowStyle Hidden\r\nStart-Sleep -Seconds 5\r\n$listed = (Get-ChildItem -LiteralPath $ad -Filter 'w.log').Length\r\n$fs = [IO.File]::Open($log, 'Open', 'Read', 'ReadWrite'); $real = $fs.Length; $fs.Close()\r\n$p.WaitForExit(); Remove-Item -LiteralPath $ad -Recurse -Force\r\n\"listed=$listed real=$real\"\r\nif ($listed -ne $real) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n}\r\n"},
{"id": "t14", "ja": "claude -p --allowedTools \u306e\u5f8c\u308d\u306b\u66f8\u3044\u305f\u30d7\u30ed\u30f3\u30d7\u30c8\u304c\u98f2\u307f\u8fbc\u307e\u308c\u308b", "en": "claude -p --allowedTools swallows the prompt after it", "claude": true, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\n$o = claude -p --allowedTools Read 'say hi' 2>&1 | Out-String\r\n($o.Trim() -split \"`n\")[0]\r\nif ($o -match 'Input must be provided') { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "h01", "ja": "Claude Code \u306e PreToolUse \u30d5\u30c3\u30af\u304c\u3001\u6642\u9593\u5207\u308c\u306b\u306a\u308b\u3068\u66f8\u304d\u8fbc\u307f\u3092\u6b62\u3081\u305a\u306b\u901a\u3059", "en": "A Claude Code PreToolUse hook lets the write through when it times out", "claude": true, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\n[IO.File]::WriteAllText(\"$d\\slow-deny.ps1\", '[IO.File]::WriteAllText(''MARK'', ''x''); Start-Sleep -Seconds 15; [Console]::Error.WriteLine(\"denied\"); exit 2'.Replace('MARK', \"$d\\called.txt\"))\r\n$hook = 'powershell -NoProfile -ExecutionPolicy Bypass -File \\\"' + ($d -replace '\\\\', '/') + '/slow-deny.ps1\\\"'\r\n[IO.File]::WriteAllText(\"$d\\s.json\", '{\"hooks\":{\"PreToolUse\":[{\"matcher\":\"Write|Edit\",\"hooks\":[{\"type\":\"command\",\"command\":\"HOOK\",\"timeout\":3}]}]}}'.Replace('HOOK', $hook))\r\nPush-Location $d\r\n'Use the Write tool once to create the file written.txt with the content hi. Do not retry if it is blocked.' | claude -p --settings s.json --permission-mode acceptEdits | Out-Null\r\nPop-Location\r\n$w = Test-Path \"$d\\written.txt\"; $c = Test-Path \"$d\\called.txt\"\r\n\"hook denies after 15 s, timeout 3 s: hook called=$c, written=$w\"\r\nif (-not $c) { 'CANNOT CHECK (the hook was never called: check disableAllHooks or your settings)' } elseif ($w) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "h02", "ja": "PowerShell \u306e\u30d5\u30c3\u30af\u3092 -Command \u3067\u547c\u3076\u3068\u3001Claude Code \u306e\u62d2\u5426\u304c\u7d20\u901a\u308a\u3059\u308b", "en": "A PowerShell hook called with -Command does not block Claude Code", "claude": true, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\n[IO.File]::WriteAllText(\"$d\\deny.ps1\", '[IO.File]::WriteAllText(''MARK'', ''x''); [Console]::Error.WriteLine(\"denied\"); exit 2'.Replace('MARK', \"$d\\called.txt\"))\r\n$hook = 'powershell -NoProfile -ExecutionPolicy Bypass -Command \\\"& ''' + ($d -replace '\\\\', '/') + '/deny.ps1''\\\"'\r\n[IO.File]::WriteAllText(\"$d\\s.json\", '{\"hooks\":{\"PreToolUse\":[{\"matcher\":\"Write|Edit\",\"hooks\":[{\"type\":\"command\",\"command\":\"HOOK\"}]}]}}'.Replace('HOOK', $hook))\r\nPush-Location $d\r\n'Use the Write tool once to create the file written.txt with the content hi. Do not retry if it is blocked.' | claude -p --settings s.json --permission-mode acceptEdits | Out-Null\r\nPop-Location\r\n$w = Test-Path \"$d\\written.txt\"; $c = Test-Path \"$d\\called.txt\"\r\n\"deny hook called through -Command: hook called=$c, written=$w\"\r\nif (-not $c) { 'CANNOT CHECK (the hook was never called: check disableAllHooks or your settings)' } elseif ($w) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "h03", "ja": "Claude Code \u306e\u30d5\u30c3\u30af\u304c1\u3064\u3082\u52d5\u304b\u306a\u3044\uff08disableAllHooks \u304c\u6b8b\u3063\u3066\u3044\u308b\uff09", "en": "No Claude Code hook runs at all (disableAllHooks is still set)", "claude": true, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\nforeach ($f in @(\"$env:USERPROFILE\\.claude\\settings.json\", \"$PWD\\.claude\\settings.json\", \"$PWD\\.claude\\settings.local.json\")) {\r\n  if (Test-Path -LiteralPath $f) { try { $v = (Get-Content -LiteralPath $f -Raw -Encoding UTF8 | ConvertFrom-Json).disableAllHooks; \"your settings: $f -> disableAllHooks=$v\" } catch { \"your settings: $f -> not valid JSON\" } }\r\n}\r\n[IO.File]::WriteAllText(\"$d\\deny.ps1\", '[IO.File]::WriteAllText(''MARK'', ''x''); [Console]::Error.WriteLine(\"denied\"); exit 2'.Replace('MARK', \"$d\\called.txt\"))\r\n$hook = 'powershell -NoProfile -ExecutionPolicy Bypass -File \\\"' + ($d -replace '\\\\', '/') + '/deny.ps1\\\"'\r\n[IO.File]::WriteAllText(\"$d\\s.json\", '{\"disableAllHooks\":true,\"hooks\":{\"PreToolUse\":[{\"matcher\":\"Write|Edit\",\"hooks\":[{\"type\":\"command\",\"command\":\"HOOK\",\"onFailure\":\"block\"}]}]}}'.Replace('HOOK', $hook))\r\nPush-Location $d\r\n'Use the Write tool once to create the file written.txt with the content hi. Do not retry if it is blocked.' | claude -p --settings s.json --permission-mode acceptEdits | Out-Null\r\nPop-Location\r\n$w = Test-Path \"$d\\written.txt\"; $c = Test-Path \"$d\\called.txt\"\r\n\"deny hook with onFailure block, plus disableAllHooks true: hook called=$c, written=$w\"\r\nif ((-not $c) -and $w) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "h04", "ja": "Python \u3067\u66f8\u3044\u305f Claude Code \u306e\u62d2\u5426\u30d5\u30c3\u30af\u304c\u3001\u65e5\u672c\u8a9e\u306e\u30d5\u30a9\u30eb\u30c0\u3067\u3060\u3051\u66f8\u304d\u8fbc\u307f\u3092\u901a\u3059", "en": "A Python deny hook lets Claude Code write into a folder with a non-ASCII (Japanese) name", "claude": true, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\n$jp = [string][char]0x65E5 + [char]0x672C + [char]0x8A9E\r\n$t = Join-Path $d $jp; New-Item -ItemType Directory $t -Force | Out-Null\r\n$py = & python -c \"import sys; print(sys.executable)\" 2>$null | Select-Object -First 1\r\nif (-not $py) { 'CANNOT CHECK (python not found, or only the Microsoft Store stub: install Python from python.org)' } else {\r\n[IO.File]::WriteAllText(\"$d\\deny_all.py\", \"import sys, json`nopen(r'MARK', 'w').close()`ndata = json.load(sys.stdin)`nprint(json.dumps({'hookSpecificOutput': {'hookEventName': 'PreToolUse', 'permissionDecision': 'deny', 'permissionDecisionReason': 'deny_all'}}))`n\".Replace('MARK', \"$d\\called.txt\"))\r\n$hook = '\\\"' + ($py -replace '\\\\', '/') + '\\\" \\\"' + ($d -replace '\\\\', '/') + '/deny_all.py\\\"'\r\n[IO.File]::WriteAllText(\"$d\\s.json\", '{\"hooks\":{\"PreToolUse\":[{\"matcher\":\"Write|Edit\",\"hooks\":[{\"type\":\"command\",\"command\":\"HOOK\"}]}]}}'.Replace('HOOK', $hook))\r\n[IO.File]::WriteAllText(\"$d\\prompt.md\", \"Use the Write tool once to create the file $t\\written.txt with the content hi. Do not retry if it is blocked.\", (New-Object Text.UTF8Encoding $false))\r\nPush-Location $d\r\n\"Read the file $d\\prompt.md and do exactly what it says.\" | claude -p --settings s.json --permission-mode acceptEdits --allowedTools \"Read,Write\" | Out-Null\r\nPop-Location\r\n$w = Test-Path \"$t\\written.txt\"; $c = Test-Path \"$d\\called.txt\"\r\n\"deny-all Python hook, target folder with a Japanese name: hook called=$c, written=$w\"\r\nif (-not $c) { 'CANNOT CHECK (the hook was never called: check disableAllHooks or your settings)' } elseif ($w) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n}\r\n"},
{"id": "h05", "ja": "Claude Code \u306e\u30d5\u30c3\u30af\u306e\u30d1\u30b9\u3092 \\ \u3067\u66f8\u304f\u3068\u3001\u30d5\u30c3\u30af\u304c\u8d77\u52d5\u305b\u305a\u66f8\u304d\u8fbc\u307f\u304c\u901a\u308b\uff08\u7d42\u4e86\u30b3\u30fc\u30c9 127\uff09", "en": "A Claude Code hook path written with backslashes never starts, and the write goes through (exit code 127)", "claude": true, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\n$cmd = (@('@echo off', 'more > nul', 'echo x> \"MARK\"', 'exit /b 2') -join \"`r`n\").Replace('MARK', \"$d\\called.txt\")\r\n[IO.File]::WriteAllText(\"$d\\deny.cmd\", $cmd + \"`r`n\")\r\n$fwd = '\\\"' + ($d -replace '\\\\', '/') + '/deny.cmd\\\"'\r\n$back = ($d + '\\deny.cmd') -replace '\\\\', '\\\\'\r\nforeach ($k in @('fwd', 'back')) {\r\n  $w = Join-Path $d $k; New-Item -ItemType Directory $w -Force | Out-Null\r\n  $hook = if ($k -eq 'fwd') { $fwd } else { $back }\r\n  [IO.File]::WriteAllText(\"$w\\s.json\", '{\"hooks\":{\"PreToolUse\":[{\"matcher\":\"Write|Edit\",\"hooks\":[{\"type\":\"command\",\"command\":\"HOOK\"}]}]}}'.Replace('HOOK', $hook))\r\n  Push-Location $w\r\n  'Use the Write tool once to create the file written.txt with the content hi. Do not retry if it is blocked.' | claude -p --settings s.json --permission-mode acceptEdits | Out-Null\r\n  Pop-Location\r\n  if ($k -eq 'fwd') { $c = Test-Path \"$d\\called.txt\" }\r\n}\r\n$wf = Test-Path \"$d\\fwd\\written.txt\"; $wb = Test-Path \"$d\\back\\written.txt\"\r\n\"same deny.cmd: quoted C:/.../deny.cmd -> hook called=$c, written=$wf; unquoted C:\\...\\deny.cmd -> written=$wb\"\r\nif ((-not $c) -or $wf) { 'CANNOT CHECK (the quoted forward-slash hook did not block: check Git for Windows, disableAllHooks or your settings)' } elseif ($wb) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "h06", "ja": "Windows \u306e\u77ed\u3044\u540d\u524d\uff088.3\uff09\u3067 Claude Code \u306b Write\u30fbEdit \u3055\u305b\u308b\u3068\u3001\u5143\u306e\u30d5\u30a1\u30a4\u30eb\u540d\u304c\u6d88\u3048\u308b", "en": "Writing through a Windows 8.3 short name makes Claude Code drop the original file name", "claude": true, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\nSet-Content -LiteralPath \"$d\\app.settings.json\" -Value old\r\n$short = (cmd /c dir /x \"$d\" | Select-String 'app\\.settings\\.json' | ForEach-Object { ($_.Line -split '\\s+') | Where-Object { $_ -match '~[0-9]' } } | Select-Object -First 1)\r\nif (-not $short) { 'CANNOT CHECK (no 8.3 short name on this drive: dir /x shows none, so this cannot happen here)' } else {\r\n\"short name: $short\"\r\nPush-Location $d\r\n\"Use the Write tool once to overwrite the file $short in the current folder with the single line new. Use exactly that file name. Do not use any other tool. Do not retry.\" | claude -p --permission-mode bypassPermissions | Out-Null\r\nPop-Location\r\n$long = Test-Path -LiteralPath \"$d\\app.settings.json\"\r\n$names = (Get-ChildItem -LiteralPath $d -Force | ForEach-Object { $_.Name }) -join ', '\r\n\"after the write: files = $names\"\r\nif ((-not $long) -and ($names -match [regex]::Escape($short))) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n}\r\n"},
{"id": "h07", "ja": "Claude Code \u3067\u88cf\u306e Bash \u3092 TaskStop \u3067\u6b62\u3081\u3066\u3082\u3001& \u3084\u30d1\u30a4\u30d7\u3067\u52d5\u304b\u3057\u305f\u30d7\u30ed\u30bb\u30b9\u304c\u6b8b\u308b", "en": "Stopping a background Bash task in Claude Code with TaskStop leaves the processes started with & or a pipe running", "claude": true, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\n[IO.File]::WriteAllText(\"$d\\p.txt\", \"Do exactly these steps and nothing else:`n1. Use the Bash tool with run_in_background set to true to run exactly this command: sleep 123 & timeout 124 sleep 122 & sleep 125 | cat`n2. Use the TaskStop tool to stop that background task.`n3. Reply STOPPED and the task id.\")\r\nPush-Location $d\r\n$o = Get-Content \"$d\\p.txt\" -Raw | claude -p --allowedTools \"Bash,TaskStop\" | Out-String\r\nPop-Location\r\nStart-Sleep -Seconds 3\r\n$left = @(Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -match 'sleep(\\.exe)?\"?\\s+12[235]\\b' })\r\n\"claude said: $($o.Trim())\"\r\n\"processes still running after claude -p ended: $($left.Count)\"\r\n$left | ForEach-Object { '  ' + $_.ProcessId + ' ' + $_.CommandLine }\r\n'(leftover sleep processes end by themselves within about two minutes)'\r\nif ($o -notmatch 'STOPPED') { 'CANNOT CHECK (claude did not report STOPPED: check that the Bash and TaskStop tools are available and allowed)' } elseif ($left.Count -gt 0) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "h08", "ja": "claude -w -p \u304c\u7d42\u308f\u3063\u305f\u3042\u3068\u3082\u3001git \u306e worktree \u306e\u30ed\u30c3\u30af\u304c\u6b8b\u3063\u3066\u6d88\u305b\u306a\u3044", "en": "After claude -w -p exits, the git worktree stays locked and cannot be removed", "claude": true, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\nPush-Location $d\r\ngit init -q 2>$null\r\ngit -c user.name=t -c user.email=t@example.invalid commit -q --allow-empty -m init 2>$null\r\n'Reply with the single word OK.' | claude -w e1 -p | Out-Null\r\n$list = git worktree list --porcelain 2>$null | Out-String\r\nPop-Location\r\n$wt = ([regex]::Matches($list, '(?m)^worktree ')).Count\r\n$lock = $list -match 'locked claude'\r\n\"worktrees: $wt; lock line after claude -p ended: $lock\"\r\n($list -split \"`n\") | Where-Object { $_ -match '^locked' }\r\nif ($wt -lt 2) { 'CANNOT CHECK (claude -w did not make a worktree: check that git is installed and claude -w works here)' } elseif ($lock) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "h09", "ja": "Claude Code \u306e Bash \u30c4\u30fc\u30eb\u3067\u3001$$( \u3092\u542b\u3080\u30b3\u30de\u30f3\u30c9\u304c\u300c\u524a\u9664\u306e\u5b89\u5168\u78ba\u8a8d\u300d\u3067\u6b62\u307e\u308b", "en": "A Claude Code Bash command containing $$( is stopped by the dangerous-removal check", "claude": true, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\n[IO.File]::WriteAllText(\"$d\\p1.txt\", 'Run exactly this Bash command and nothing else, then stop: echo ''a$$(b'' > x.txt')\r\n[IO.File]::WriteAllText(\"$d\\p2.txt\", 'Run exactly this Bash command and nothing else, then stop: echo ''a$(b'' > y.txt')\r\nPush-Location $d\r\nGet-Content \"$d\\p2.txt\" -Raw | claude -p --allowedTools Bash | Out-Null\r\nGet-Content \"$d\\p1.txt\" -Raw | claude -p --allowedTools Bash | Out-Null\r\nPop-Location\r\n$y = Test-Path \"$d\\y.txt\"; $x = Test-Path \"$d\\x.txt\"\r\n\"echo with one dollar and a paren -> written=$y; echo with two dollars and a paren -> written=$x\"\r\nif (-not $y) { 'CANNOT CHECK (even the one-dollar command did not run: check that the Bash tool is available and allowed)' } elseif (-not $x) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "h10", "ja": "Windows \u306e Claude Code \u306e Bash \u30c4\u30fc\u30eb\u3067\u3001\\\\\uff08\u30d0\u30c3\u30af\u30b9\u30e9\u30c3\u30b7\u30e52\u3064\uff09\u304c \\ 1\u3064\u306b\u306a\u308b", "en": "On Windows, Claude Code's Bash tool turns \\\\ (two backslashes) into one", "claude": true, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\n[IO.File]::WriteAllText(\"$d\\p.txt\", 'Use the Bash tool once to run exactly this command and nothing else, then stop: printf ''%s'' ''a\\\\b'' > out.bin')\r\nPush-Location $d\r\nGet-Content \"$d\\p.txt\" -Raw | claude -p --allowedTools Bash | Out-Null\r\nPop-Location\r\nif (-not (Test-Path \"$d\\out.bin\")) { 'CANNOT CHECK (out.bin was not written: check that the Bash tool is available and allowed)' } else {\r\n$b = [IO.File]::ReadAllBytes(\"$d\\out.bin\")\r\n\"asked for a, two backslashes, b -> bytes written: \" + (($b | ForEach-Object { '{0:x2}' -f $_ }) -join ' ')\r\nif ($b.Length -eq 3) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n}\r\n"},
{"id": "h12", "ja": "Claude Code \u306e PowerShell \u30c4\u30fc\u30eb\u3067\u3001cd \u3057\u305f\u30d5\u30a9\u30eb\u30c0\u304c\u6b21\u306e\u547c\u3073\u51fa\u3057\u3067\u5143\u306b\u623b\u308b", "en": "Claude Code's PowerShell tool goes back to the start folder on the next call after cd", "claude": true, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\nforeach ($v in @('1', '0')) {\r\n  $w = Join-Path $d \"v$v\"; New-Item -ItemType Directory \"$w\\sub\" -Force | Out-Null\r\n  [IO.File]::WriteAllText(\"$w\\s.json\", '{\"env\":{\"CLAUDE_BASH_MAINTAIN_PROJECT_WORKING_DIR\":\"VAL\",\"CLAUDE_CODE_USE_POWERSHELL_TOOL\":\"1\"}}'.Replace('VAL', $v))\r\n  $p = 'You must use the PowerShell tool (not Bash). Call 1: Set-Location sub . Call 2 (a separate PowerShell tool call): [IO.File]::WriteAllText(\"OUT\", (Get-Location).Path) . Then stop.'.Replace('OUT', \"$w\\call2.txt\")\r\n  Push-Location $w\r\n  $p | claude -p --settings s.json --allowedTools PowerShell | Out-Null\r\n  Pop-Location\r\n}\r\n$r1 = ''; $r0 = ''\r\nif (Test-Path \"$d\\v1\\call2.txt\") { $r1 = (Get-Content \"$d\\v1\\call2.txt\" -Raw).Trim() }\r\nif (Test-Path \"$d\\v0\\call2.txt\") { $r0 = (Get-Content \"$d\\v0\\call2.txt\" -Raw).Trim() }\r\n\"second PowerShell call after cd sub: MAINTAIN=1 -> $r1 ; MAINTAIN=0 -> $r0\"\r\nif ((-not $r0) -or (-not $r1)) { 'CANNOT CHECK (the PowerShell tool did not run: it needs a Claude Code version with the PowerShell tool)' } elseif (-not $r0.EndsWith('sub')) { 'CANNOT CHECK (even with MAINTAIN=0 the cd did not stay)' } elseif (-not $r1.EndsWith('sub')) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "h11", "ja": "Windows \u306e Claude Code \u306e Bash \u30c4\u30fc\u30eb\u3067\u3001%TEMP% \u306e\u4e0b\u3078\u306e cd \u304c\u6b21\u306e\u547c\u3073\u51fa\u3057\u3067\u53d6\u308a\u6d88\u3055\u308c\u308b", "en": "On Windows, a cd into %TEMP% in Claude Code's Bash tool is undone on the next call", "claude": true, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\nNew-Item -ItemType Directory \"$d\\sub\" -Force | Out-Null\r\n$u = $d -replace '\\\\', '/'\r\n$p = 'Use the Bash tool exactly twice, one command per call. Call 1: cd \"U/sub\" && pwd > \"U/p1.txt\" . Call 2: pwd > \"U/p2.txt\" . Then stop.'.Replace('U', $u)\r\nPush-Location $d\r\n$p | claude -p --allowedTools Bash | Out-Null\r\nPop-Location\r\nif (-not (Test-Path \"$d\\p1.txt\") -or -not (Test-Path \"$d\\p2.txt\")) { 'CANNOT CHECK (the Bash tool did not run both calls: check that it is available and allowed)' } else {\r\n$p1 = (Get-Content \"$d\\p1.txt\" -Raw).Trim(); $p2 = (Get-Content \"$d\\p2.txt\" -Raw).Trim()\r\n\"inside %TEMP%: same call after cd sub -> $p1 ; next call -> $p2\"\r\nif (-not $p1.EndsWith('/sub')) { 'CANNOT CHECK (cd did not work even inside the same call)' } elseif (-not $p2.EndsWith('/sub')) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n}\r\n"},
{"id": "h13", "ja": "claude -p \u306e --json-schema \u304c\u3001\u9053\u5177\u3092\u7d5e\u3063\u305f --agent \u3092\u4ed8\u3051\u308b\u3068\u9ed9\u3063\u3066\u52b9\u304b\u306a\u3044\uff08\u6210\u529f\u306e\u307e\u307e\uff09", "en": "claude -p --json-schema silently stops working with an --agent that restricts tools (still reports success)", "claude": true, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\nNew-Item -ItemType Directory -Force \"$d\\.claude\\agents\" | Out-Null\r\n[IO.File]::WriteAllText(\"$d\\.claude\\agents\\ro.md\", \"---`nname: ro`ndescription: read-only test agent`ntools: Read`n---`nYou answer questions briefly.`n\")\r\n$schema = '{\\\"type\\\":\\\"object\\\",\\\"properties\\\":{\\\"answer\\\":{\\\"type\\\":\\\"string\\\"}},\\\"required\\\":[\\\"answer\\\"]}'\r\n$q = 'What is 2+2? Reply with the answer.'\r\nPush-Location $d\r\n$a = $q | claude -p --model haiku --json-schema $schema --output-format json | Out-String\r\n$b = $q | claude -p --model haiku --json-schema $schema --agent ro --output-format json | Out-String\r\nPop-Location\r\n$ha = $a -match '\"structured_output\"'; $hb = $b -match '\"structured_output\"'; $ok = $b -match '\"subtype\":\"success\"'\r\n\"without --agent: structured_output=$ha; with --agent ro: structured_output=$hb, subtype success=$ok\"\r\nif (-not $ha) { 'CANNOT CHECK (even without --agent there was no structured_output: check that claude -p works and is logged in)' } elseif ((-not $hb) -and $ok) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "h15", "ja": "\u30b5\u30d6\u30d5\u30a9\u30eb\u30c0\u306e CLAUDE.md \u3092\u4e00\u90e8\u3060\u3051 Read \u3059\u308b\u3068\u3001\u6b8b\u308a\u304c\u9ed9\u3063\u3066\u8aad\u307f\u8fbc\u307e\u308c\u306a\u304f\u306a\u308b", "en": "A partial Read of a subdirectory CLAUDE.md silently stops the rest of it from loading", "claude": true, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\n$res = @{}\r\nforeach ($case in 'partial', 'plain') {\r\n    $t = Join-Path $d $case\r\n    New-Item -ItemType Directory -Force (Join-Path $t 'sub') | Out-Null\r\n    $lines = 1..30 | ForEach-Object { \"Rule $_`: keep files tidy.\" }\r\n    $lines += 'MARKER: the code word for this folder is PELICAN.'\r\n    [IO.File]::WriteAllText((Join-Path $t 'sub\\CLAUDE.md'), ($lines -join \"`n\") + \"`n\")\r\n    [IO.File]::WriteAllText((Join-Path $t 'sub\\a.txt'), \"hello`n\")\r\n    $ask = 'Without reading any file again, reply with the code word for the sub folder if any instructions you have contain one, otherwise reply UNKNOWN.'\r\n    if ($case -eq 'partial') { $p = \"Do exactly this: 1. Use the Read tool on sub/CLAUDE.md with offset 1 and limit 1. 2. Use the Read tool on sub/a.txt. 3. $ask\" }\r\n    else { $p = \"Do exactly this: 1. Use the Read tool on sub/a.txt. 2. $ask\" }\r\n    Push-Location $t\r\n    $out = $p | claude -p --allowedTools Read --output-format json | Out-String\r\n    Pop-Location\r\n    $res[$case] = $out -match 'PELICAN'\r\n}\r\n\"knows the code word: after a partial Read first = $($res['partial']); without it = $($res['plain'])\"\r\nif (-not $res['plain']) { 'CANNOT CHECK (even without the partial Read the code word was not known: check that claude -p works and is logged in)' } elseif (-not $res['partial']) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "h17", "ja": "\u30ea\u30dd\u30b8\u30c8\u30ea\u306e\u30b5\u30d6\u30d5\u30a9\u30eb\u30c0\u3067 Claude Code \u3092\u8d77\u52d5\u3059\u308b\u3068\u3001\u30eb\u30fc\u30c8\u306e .claude/settings.json \u306e\u30d5\u30c3\u30af\u304c\u52b9\u304b\u306a\u3044", "en": "Start Claude Code in a repo subfolder and the hooks in the root .claude/settings.json do not run", "claude": true, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\n$repo = Join-Path $d 'hookrepo'\r\nNew-Item -ItemType Directory -Force \"$repo\\.claude\", \"$repo\\sub\\deep\" | Out-Null\r\nPush-Location $repo; git init -q 2>$null; Pop-Location\r\n$mark = ($repo + '\\hook-ran.txt').Replace('\\', '/')\r\n$cmd = 'python -c \"open(r''' + $mark + ''',''a'').write(''x'')\"'\r\n$settings = @{ hooks = @{ PreToolUse = @(@{ matcher = 'Read'; hooks = @(@{ type = 'command'; command = $cmd }) }) } } | ConvertTo-Json -Depth 8\r\n[IO.File]::WriteAllText(\"$repo\\.claude\\settings.json\", $settings)\r\n[IO.File]::WriteAllText(\"$repo\\sub\\deep\\a.txt\", \"hello`n\")\r\n[IO.File]::WriteAllText(\"$repo\\a.txt\", \"hello`n\")\r\n$ran = @{}\r\nforeach ($where in 'root', 'sub\\deep') {\r\n    Remove-Item -LiteralPath \"$repo\\hook-ran.txt\" -ErrorAction SilentlyContinue\r\n    Push-Location (Join-Path $repo ($where -replace 'root', ''))\r\n    'Use the Read tool once on a.txt and reply done.' | claude -p --allowedTools Read | Out-Null\r\n    Pop-Location\r\n    $ran[$where] = Test-Path \"$repo\\hook-ran.txt\"\r\n}\r\n\"root hook ran when started at the repo root: $($ran['root']); when started in sub\\deep: $($ran['sub\\deep'])\"\r\nif (-not $ran['root']) { 'CANNOT CHECK (the hook did not run even at the root: check that python and git are installed)' } elseif (-not $ran['sub\\deep']) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "h19", "ja": "\u30b8\u30e3\u30f3\u30af\u30b7\u30e7\u30f3\u306e\u4e0b\u3067 Claude Code \u3092\u8d77\u52d5\u3059\u308b\u3068\u3001\u4f5c\u696d\u30d5\u30a9\u30eb\u30c0\u304c\u672c\u5f53\u306e\u30d1\u30b9\u306b\u7f6e\u304d\u63db\u308f\u308b\uff08\u30d5\u30c3\u30af\u306b\u3082\uff09", "en": "Start Claude Code under a junction and the working folder is silently replaced by the real path (hooks too)", "claude": true, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\n$real = Join-Path $d 'real'\r\n$link = Join-Path $d 'link'\r\nNew-Item -ItemType Directory -Force \"$real\\repo\" | Out-Null\r\ncmd /c mklink /J \"$link\" \"$real\" | Out-Null\r\ngit -C \"$real\\repo\" init -q 2>$null\r\nif (-not (Test-Path \"$link\\repo\")) { 'CANNOT CHECK (could not create the junction with mklink /J)' } else {\r\nPush-Location \"$link\\repo\"\r\n$init = 'reply ok' | claude -p --model haiku --output-format stream-json --verbose --max-turns 1 | Where-Object { $_ -match '\"subtype\":\"init\"' } | Select-Object -First 1\r\nPop-Location\r\n$cwd = [regex]::Match([string]$init, '\"cwd\":\"([^\"]+)\"').Groups[1].Value.Replace('\\\\', '\\')\r\n\"launched in: $link\\repo\"\r\n\"init cwd   : $cwd\"\r\nif (-not $cwd) { 'CANNOT CHECK (no init line from claude -p: check that claude -p works and is logged in)' } elseif ($cwd -like '*\\real\\repo') { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n}\r\n"},
{"id": "h14", "ja": "Windows \u306e Claude Code \u306e Bash \u30c4\u30fc\u30eb\u306f\u30017,400 \u6587\u5b57\u307b\u3069\u3092\u8d85\u3048\u308b\u30b3\u30de\u30f3\u30c9\u3092\u52d5\u304b\u3055\u306a\u3044\uff08\u30a8\u30e9\u30fc\u306f\u300c\u5f15\u7528\u7b26\u304c\u9589\u3058\u3066\u3044\u306a\u3044\u300d\uff09", "en": "On Windows, Claude Code's Bash tool does not run commands longer than about 7,400 characters (the error says a quote is unmatched)", "claude": true, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\n$hook = @'\r\nimport json, sys\r\nfrom pathlib import Path\r\nd = json.load(sys.stdin)\r\nif d.get(\"tool_name\") != \"Bash\":\r\n    sys.exit(0)\r\nn = int(Path(\"n.txt\").read_text().strip())\r\ncmd = \"printf %s '\" + \"A\" * n + \"' > o.txt; echo ok > d.txt\"\r\nprint(json.dumps({\"hookSpecificOutput\": {\"hookEventName\": \"PreToolUse\", \"permissionDecision\": \"allow\", \"updatedInput\": {\"command\": cmd}}}))\r\n'@\r\n[IO.File]::WriteAllText(\"$d\\hook.py\", $hook)\r\n$hp = ($d + '\\hook.py').Replace('\\', '/')\r\n[IO.File]::WriteAllText(\"$d\\s.json\", '{\"hooks\":{\"PreToolUse\":[{\"matcher\":\"Bash\",\"hooks\":[{\"type\":\"command\",\"command\":\"python \\\"HP\\\"\"}]}]}}'.Replace('HP', $hp))\r\n$ok = @{}\r\nPush-Location $d\r\nforeach ($n in 7000, 7600) {\r\n    Remove-Item -LiteralPath \"$d\\o.txt\", \"$d\\d.txt\" -ErrorAction SilentlyContinue\r\n    [IO.File]::WriteAllText(\"$d\\n.txt\", \"$n\")\r\n    'Use the Bash tool once to run: echo hi . Then stop.' | claude -p --settings s.json --allowedTools Bash | Out-Null\r\n    $ok[$n] = (Test-Path \"$d\\d.txt\")\r\n}\r\nPop-Location\r\n\"a 7000-A command ran to the end: $($ok[7000]); a 7600-A command ran to the end: $($ok[7600])\"\r\nif (-not $ok[7000]) { 'CANNOT CHECK (even the 7000-character command did not run: check that python is installed and the Bash tool works)' } elseif (-not $ok[7600]) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "h21", "ja": "\u30d5\u30c3\u30af\u306e .ps1 \u304c\u898b\u3064\u304b\u3089\u306a\u3044\u3068\u3001onFailure: block \u3067\u3082\u66f8\u304d\u8fbc\u307f\u304c\u901a\u308b", "en": "If a hook's .ps1 file is missing, writes go through even with onFailure: block", "claude": true, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\nNew-Item -ItemType Directory -Force \"$d\\.claude\" | Out-Null\r\n$settings = @'\r\n{\r\n  \"hooks\": {\r\n    \"PreToolUse\": [\r\n      {\r\n        \"matcher\": \"Write\",\r\n        \"hooks\": [\r\n          {\r\n            \"type\": \"command\",\r\n            \"command\": \"powershell.exe\",\r\n            \"args\": [\"-NoProfile\", \"-ExecutionPolicy\", \"Bypass\", \"-File\", \"${CLAUDE_PROJECT_DIR}/.claude/hooks/missing-script.ps1\"],\r\n            \"onFailure\": \"block\",\r\n            \"timeout\": 30\r\n          }\r\n        ]\r\n      }\r\n    ]\r\n  }\r\n}\r\n'@\r\n[IO.File]::WriteAllText(\"$d\\.claude\\settings.json\", $settings)\r\nPush-Location $d\r\n'Use the Write tool once to create out.txt with the text hi. Do not retry. Then reply done.' | claude -p --allowedTools Write | Out-Null\r\nPop-Location\r\n& powershell.exe -NoProfile -ExecutionPolicy Bypass -File \"$d\\.claude\\hooks\\missing-script.ps1\" 2>$null | Out-Null\r\n$code = $LASTEXITCODE\r\n$w = Test-Path \"$d\\out.txt\"\r\n\"exit code of powershell -File <missing .ps1>: $code; out.txt written despite onFailure block: $w\"\r\nif ($w) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "h16", "ja": "Windows \u306e Claude Code \u3067 Edit\u30fbWrite \u3059\u308b\u3068\u3001\u30d5\u30a1\u30a4\u30eb\u540d\u306e\u5927\u6587\u5b57\u5c0f\u6587\u5b57\u304c\u9ed9\u3063\u3066\u5909\u308f\u308b", "en": "On Windows, Claude Code's Edit and Write silently change the letter case of the file name", "claude": true, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\nNew-Item -ItemType Directory -Force \"$d\\Sub\" | Out-Null\r\n[IO.File]::WriteAllText(\"$d\\Sub\\EditBack.txt\", \"fruit = APPLE`r`n\")\r\nPush-Location $d\r\n\"First use the Read tool on the file Sub/EditBack.txt in the current folder. Then use the Edit tool exactly once with file_path set to exactly this string, character for character: $d\\sub\\editback.TXT . Replace APPLE with ORANGE. Use no other tools. Then stop.\" | claude -p --allowedTools \"Read,Edit\" | Out-Null\r\nPop-Location\r\n$name = (Get-ChildItem -LiteralPath \"$d\\Sub\" | ForEach-Object Name) -join ', '\r\n$body = (Get-Content -LiteralPath \"$d\\Sub\\EditBack.txt\" -Raw).Trim()\r\n\"file name after the Edit: $name; content: $body\"\r\nif ($body -notmatch 'ORANGE') { 'CANNOT CHECK (the Edit did not happen: check that claude -p can use Read and Edit)' } elseif ($name -ceq 'editback.TXT') { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "h23", "ja": "Git Bash \u306e\u30d5\u30c3\u30af\u3067 $PWD \u3068 file_path \u3092\u6bd4\u3079\u308b\u3068\u3001Windows \u3067\u306f\u30d7\u30ed\u30b8\u30a7\u30af\u30c8\u306e\u4e2d\u307e\u3067\u300c\u5916\u300d\u306b\u306a\u308b", "en": "A Git Bash hook that compares $PWD with file_path treats even files inside the project as outside on Windows", "claude": true, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\nNew-Item -ItemType Directory -Force \"$d\\.claude\\hooks\" | Out-Null\r\nPush-Location $d; git init -q 2>$null; Pop-Location\r\n$sh = @'\r\nf=$(python -c \"import sys,json; print(json.load(sys.stdin)['tool_input'].get('file_path',''))\")\r\nprintf 'PWD=%s\\nfile_path=%s\\n' \"$PWD\" \"$f\" > seen.txt\r\ncase \"$f\" in \"$PWD\"/*) exit 0;; *) echo \"BLOCKED: file outside the project\" >&2; exit 2;; esac\r\n'@\r\n[IO.File]::WriteAllText(\"$d\\.claude\\hooks\\guard.sh\", $sh.Replace(\"`r`n\", \"`n\"))\r\n[IO.File]::WriteAllText(\"$d\\.claude\\settings.json\", '{\"hooks\":{\"PreToolUse\":[{\"matcher\":\"Write\",\"hooks\":[{\"type\":\"command\",\"command\":\"bash .claude/hooks/guard.sh\"}]}]}}')\r\nPush-Location $d\r\n'Use the Write tool once to create out.txt in the current folder with the text hi. Do not retry. Then reply done.' | claude -p --allowedTools Write | Out-Null\r\nPop-Location\r\nif (Test-Path \"$d\\seen.txt\") { Get-Content \"$d\\seen.txt\" }\r\n$w = Test-Path \"$d\\out.txt\"\r\n\"write inside the project went through: $w\"\r\nif (-not (Test-Path \"$d\\seen.txt\")) { 'CANNOT CHECK (the hook did not run: check that python, git and Git for Windows bash are installed)' } elseif (-not $w) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "h18", "ja": "Windows \u306e Claude Code \u306f\u3001\u30d1\u30b9\u306e\u30c9\u30e9\u30a4\u30d6\u6587\u5b57\u304c\u5c0f\u6587\u5b57\uff08c:\\\uff09\u3060\u3068\u3001\u4e0b\u306e\u30d5\u30a9\u30eb\u30c0\u306e CLAUDE.md \u3092\u8aad\u307e\u306a\u3044", "en": "On Windows, Claude Code skips a subfolder's CLAUDE.md when the path's drive letter is lowercase (c:\\)", "claude": true, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\nNew-Item -ItemType Directory -Force \"$d\\sub\" | Out-Null\r\n[IO.File]::WriteAllText(\"$d\\sub\\CLAUDE.md\", \"# Rules for this folder`nWhenever you answer after reading a file in this folder, end your answer with the code word ZEBRA-42.`n\")\r\n[IO.File]::WriteAllText(\"$d\\sub\\a.txt\", \"hello`n\")\r\nSet-Location $d\r\n$lower = 'c' + $d.Substring(1)\r\n$got = @()\r\nforeach ($p in \"$d\\sub\\a.txt\", \"$lower\\sub\\a.txt\") {\r\n    $ans = \"Use the Read tool once with file_path set to exactly this string: $p . Then reply with the file's content and follow any instructions you were given for that folder.\" | claude -p --allowedTools Read | Out-String\r\n    $got += ($ans -match 'ZEBRA-42')\r\n}\r\n\"sub\\CLAUDE.md applied with C:\\ path: $($got[0]); with c:\\ path: $($got[1])\"\r\nif ($d.Substring(0, 2) -ne 'C:') { 'CANNOT CHECK (TEMP is not on drive C:)' } elseif (-not $got[0]) { 'CANNOT CHECK (the folder CLAUDE.md was not applied even with C:\\: check that claude -p can use Read)' } elseif (-not $got[1]) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "h20", "ja": "Claude Code \u306e PowerShell \u30c4\u30fc\u30eb\u306f\u3001\u9014\u4e2d\u306e\u30b3\u30de\u30f3\u30c9\u306e\u7d42\u4e86\u30b3\u30fc\u30c9\u3067\u3001\u6210\u529f\u3092\u300c\u5931\u6557\u300d\u3068\u8fd4\u3059", "en": "Claude Code's PowerShell tool reports success as failure because of an earlier command's exit code", "claude": true, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\n[IO.File]::WriteAllText(\"$d\\s.json\", '{\"env\":{\"CLAUDE_CODE_USE_POWERSHELL_TOOL\":\"1\"}}')\r\nPush-Location $d\r\n$out = \"You must use the PowerShell tool (not Bash). Run exactly the PowerShell command in the next line once, then stop.`ncmd /c exit 3; 'done'\" | claude -p --settings s.json --allowedTools PowerShell --output-format stream-json --verbose | Out-String\r\nPop-Location\r\n$ran = $out -match 'done'\r\n$err = $out -match '\"is_error\":true'\r\n\"the PowerShell tool ran the command: $ran; the call was reported as an error: $err\"\r\nif (-not $ran) { 'CANNOT CHECK (the PowerShell tool did not run: check that claude -p can use it)' } elseif ($err -and ($out -match 'Exit code 3')) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "h22", "ja": "Claude Code \u306e Edit\u30fbWrite \u306f\u3001.md \u4ee5\u5916\u306e\u30d5\u30a1\u30a4\u30eb\u3067\u884c\u672b\u306e\u7a7a\u767d\u3092\u9ed9\u3063\u3066\u6d88\u3059\uff08\u30bf\u30d6\u3092\u7a7a\u767d\u306b\u7f6e\u304d\u63db\u3048\u308b\u3068\u3001\u6d88\u3048\u308b\u3060\u3051\uff09", "en": "Claude Code's Edit and Write silently strip trailing whitespace outside .md files (tabs-to-spaces just deletes the tabs)", "claude": true, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\n[IO.File]::WriteAllText(\"$d\\case.txt\", \"a`tb`tc`n1`t2`t3`n\")\r\nPush-Location $d\r\n\"Use the Read tool on case.txt, then use the Edit tool once on case.txt with old_string set to exactly one TAB character, new_string set to exactly two space characters, and replace_all true. Use no other tools. Then stop.\" | claude -p --allowedTools \"Read,Edit\" | Out-Null\r\nPop-Location\r\n$b = [IO.File]::ReadAllBytes(\"$d\\case.txt\")\r\n\"case.txt was 12 bytes with 4 tabs; asked to turn each tab into two spaces; now $($b.Length) bytes, tabs left: $(@($b | Where-Object { $_ -eq 9 }).Count)\"\r\nif ($b.Length -eq 12) { 'CANNOT CHECK (the Edit did not happen: check that claude -p can use Read and Edit)' } elseif ($b.Length -eq 8) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "h24", "ja": "Claude Code \u306e Grep \u306f\u3001\u4f5c\u696d\u30d5\u30a9\u30eb\u30c0\u306e\u4e0b\u3092\u63a2\u3059\u3068\u304d\u3001glob \u306e */ \u304c\u300c\u898b\u3064\u304b\u3089\u306a\u3044\u300d\u306b\u306a\u308b", "en": "Claude Code's Grep returns No files found for a */ glob when searching below the working folder", "claude": true, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\nNew-Item -ItemType Directory -Force \"$d\\a\\b\\sub\" | Out-Null\r\n[IO.File]::WriteAllText(\"$d\\a\\b\\sub\\SKILL.md\", \"markerterm`n\")\r\nPush-Location $d\r\n$found = @()\r\nforeach ($g in '**/SKILL.md', '*/SKILL.md') {\r\n    $out = \"Use the Grep tool exactly once with pattern set to markerterm, path set to exactly $d\\a\\b , glob set to exactly $g , and output_mode files_with_matches. Use no other tools. Then stop.\" | claude -p --allowedTools Grep --output-format stream-json --verbose | Out-String\r\n    $found += ($out -match 'Found 1 file')\r\n}\r\nPop-Location\r\n\"glob **/SKILL.md found the file: $($found[0]); glob */SKILL.md found the file: $($found[1])\"\r\nif (-not $found[0]) { 'CANNOT CHECK (even **/SKILL.md found nothing: check that claude -p can use Grep)' } elseif (-not $found[1]) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"},
{"id": "c01", "ja": "Codex CLI \u304c PowerShell 5.1 \u3067\u30d1\u30a4\u30d7\u306b\u6e21\u3057\u305f\u65e5\u672c\u8a9e\u304c ? \u306b\u306a\u308b\uff08\u7d42\u4e86\u30b3\u30fc\u30c9 0\uff09", "en": "Codex CLI on PowerShell 5.1: non-ASCII text piped to a command arrives as ? (exit code 0)", "claude": false, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\n$pyv = & python -c \"import sys; print('%d.%d.%d' % sys.version_info[:3])\" 2>$null\r\nif (-not $pyv) { 'CANNOT CHECK (python not found, or only the Microsoft Store stub: install Python from python.org)' } else {\r\n\"python $pyv\"\r\n[IO.File]::WriteAllText(\"$d\\hex.py\", 'import sys; print(sys.stdin.buffer.read().strip().hex())')\r\n$s = 'Zo' + [char]0xE9 + ' ' + [char]0x65E5 + [char]0x672C\r\n$h = $s | python \"$d\\hex.py\"\r\n\"bytes=$h  (UTF-8 would be 5a6fc3a920e697a5e69cac)\"\r\nif ($h -match '3f') { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n}\r\n"},
{"id": "c02", "ja": "Codex CLI \u304c PowerShell 5.1 \u3067\u8aad\u3093\u3060 UTF-8\uff08BOM \u306a\u3057\uff09\u306e\u65e5\u672c\u8a9e\u304c\u5316\u3051\u308b\uff08\u7d42\u4e86\u30b3\u30fc\u30c9 0\uff09", "en": "Codex CLI on PowerShell 5.1 misreads UTF-8 (no BOM) Japanese files (exit code 0)", "claude": false, "slow": false, "check": "$d = Join-Path $env:TEMP ('cc-trap-' + (Get-Date -Format 'yyyyMMddHHmmss')); New-Item -ItemType Directory $d -Force | Out-Null\r\n$s = [string][char]0x65E5 + [char]0x672C + [char]0x8A9E\r\n[IO.File]::WriteAllText(\"$d\\note.md\", $s, [Text.UTF8Encoding]::new($false))\r\n$a = Get-Content -LiteralPath \"$d\\note.md\"\r\n$b = Get-Content -LiteralPath \"$d\\note.md\" -Encoding UTF8\r\n\"default read equals the file: $($a -eq $s); with -Encoding UTF8: $($b -eq $s)\"\r\nif ($a -ne $s -and $b -eq $s) { 'REPRODUCED' } else { 'NOT REPRODUCED' }\r\n"}
]
'@ | ConvertFrom-Json
    $messages = @'
{
    "ja": {
        "header": "ID  \u7d50\u679c  \u75c7\u72b6  |  \u30da\u30fc\u30b8",
        "statuses": {
            "REPRODUCED": "\u8d77\u304d\u308b",
            "NOT REPRODUCED": "\u8d77\u304d\u306a\u3044",
            "CANNOT CHECK": "\u8abf\u3079\u3089\u308c\u306a\u3044",
            "TIMEOUT": "\u6642\u9593\u5207\u308c"
        },
        "summary": "\u3053\u306e PC \u3067\u306f\u3001\u8abf\u3079\u305f {0} \u4ef6\u306e\u3046\u3061 {1} \u4ef6\u304c\u8d77\u304d\u307e\u3057\u305f\u3002\u5404\u884c\u306e\u30da\u30fc\u30b8\u306b\u76f4\u3057\u65b9\u304c\u3042\u308a\u307e\u3059\u3002",
        "skipped_claude": "Claude \u3092\u547c\u3076 {0} \u4ef6\u306f\u3001\u4f7f\u7528\u91cf\u3092\u4f7f\u3046\u306e\u3067\u8abf\u3079\u3066\u3044\u307e\u305b\u3093\u3002\u4e00\u89a7: {1}",
        "skipped_slow": "t13 \u3082\u8abf\u3079\u308b\u306b\u306f\u3001$env:CCDOCTOR_ALL='1' \u3092\u5b9f\u884c\u3057\u3066\u304b\u3089\u3082\u3046\u4e00\u5ea6\u304a\u8a66\u3057\u304f\u3060\u3055\u3044\u3002"
    },
    "en": {
        "header": "ID  Result  Symptom  |  Page",
        "statuses": {
            "REPRODUCED": "REPRODUCED",
            "NOT REPRODUCED": "NOT REPRODUCED",
            "CANNOT CHECK": "CANNOT CHECK",
            "TIMEOUT": "TIMEOUT"
        },
        "summary": "{1} of {0} checks reproduce on this PC. Each row's page has the fix.",
        "skipped_claude": "Skipped {0} that would call Claude and count toward your usage. Index: {1}",
        "skipped_slow": "To include t13, run $env:CCDOCTOR_ALL='1' before running the doctor again."
    }
}
'@ | ConvertFrom-Json
    $baseUrl = 'https://cart231-ffly-b.github.io/cc-win-symptoms/'
    if ($env:CCDOCTOR_LANG -eq 'ja') {
        $lang = 'ja'
    } elseif ($env:CCDOCTOR_LANG -eq 'en') {
        $lang = 'en'
    } elseif ([Globalization.CultureInfo]::CurrentUICulture.TwoLetterISOLanguageName -eq 'ja' -or
        [Globalization.CultureInfo]::CurrentCulture.TwoLetterISOLanguageName -eq 'ja') {
        $lang = 'ja'
    } else {
        $lang = 'en'
    }
    $messages = $messages.$lang
    $only = $env:CCDOCTOR_ONLY -split ','

    function Invoke-DoctorCheck($trap, $workDir, $encoding) {
        $process = New-Object System.Diagnostics.Process
        $stdoutReader = $null
        $stderrReader = $null
        try {
            $localAppData = Join-Path $workDir 'LocalAppData'
            $null = [IO.Directory]::CreateDirectory($localAppData)
            $scriptPath = Join-Path $workDir ($trap.id + '.ps1')
            [IO.File]::WriteAllText($scriptPath, $trap.check, [Text.Encoding]::ASCII)

            $start = $process.StartInfo
            $start.FileName = Join-Path $PSHOME 'powershell.exe'
            $start.Arguments = '-NoProfile -ExecutionPolicy Bypass -File "' + $scriptPath + '"'
            $start.WorkingDirectory = $workDir
            $start.UseShellExecute = $false
            $start.RedirectStandardInput = $true
            $start.RedirectStandardOutput = $true
            $start.RedirectStandardError = $true
            $start.StandardOutputEncoding = $encoding
            $start.EnvironmentVariables['TEMP'] = $workDir
            $start.EnvironmentVariables['TMP'] = $workDir
            $start.EnvironmentVariables['LOCALAPPDATA'] = $localAppData

            $null = $process.Start()
            $process.StandardInput.Close()
            $watch = [Diagnostics.Stopwatch]::StartNew()
            $stdoutReader = $process.StandardOutput
            $stderrReader = $process.StandardError
            $stdout = $stdoutReader.ReadToEndAsync()
            $null = $stderrReader.BaseStream.CopyToAsync([IO.Stream]::Null)
            if (-not $process.WaitForExit(60000)) {
                # Windows PowerShell's .NET Process.Kill() only kills the immediate child.
                & (Join-Path $env:SystemRoot 'System32/taskkill.exe') /PID $process.Id /T /F 2>$null | Out-Null
                if (-not $process.HasExited) { $process.Kill() }
                $process.WaitForExit()
                return 'TIMEOUT'
            }
            if (-not $stdout.Wait([Math]::Max(0, 60000 - [int]$watch.ElapsedMilliseconds))) {
                return 'TIMEOUT'
            }

            $last = ($stdout.Result.TrimEnd() -split '\r?\n')[-1].Trim()
            if ($last -match '^(REPRODUCED|NOT REPRODUCED|CANNOT CHECK(?: \(.*\))?)$') { return $last }
            return 'CANNOT CHECK (no check result)'
        } catch {
            return 'CANNOT CHECK (could not run the check)'
        } finally {
            if ($stdoutReader) { $stdoutReader.Dispose() }
            if ($stderrReader) { $stderrReader.Dispose() }
            $process.Dispose()
        }
    }

    $tempRoot = [IO.Path]::GetFullPath($env:TEMP)
    $runDir = Join-Path $tempRoot ('cc-doctor-' + [guid]::NewGuid().ToString('N'))
    $null = [IO.Directory]::CreateDirectory($runDir)
    $savedEncoding = [Console]::OutputEncoding
    $encoding = [Text.Encoding]::GetEncoding((Get-Culture).TextInfo.OEMCodePage)
    $reproduced = 0
    $skippedClaude = 0
    $skippedSlow = $false
    $rows = @(
        try {
            [Console]::OutputEncoding = $encoding
            foreach ($trap in $traps) {
                if ($env:CCDOCTOR_ONLY -and $only -notcontains $trap.id) { continue }
                if ($trap.claude) {
                    $skippedClaude++
                    continue
                }
                if ($trap.slow -and $env:CCDOCTOR_ALL -ne '1') {
                    $skippedSlow = $true
                    continue
                }
                $result = Invoke-DoctorCheck $trap (Join-Path $runDir $trap.id) $encoding
                if ($result -eq 'REPRODUCED') { $reproduced++ }
                $status, $detail = $result -split ' \(', 2
                if ($detail) { $detail = $detail.Substring(0, $detail.Length - 1) }
                [pscustomobject]@{
                    Id = $trap.id
                    Status = $status
                    Title = $trap.$lang
                    Detail = $detail
                }
            }
        } finally {
            try { [Console]::OutputEncoding = $savedEncoding } finally { [IO.Directory]::Delete($runDir, $true) }
        }
    )

    if ($env:CCDOCTOR_JSON) {
        $jsonRows = @($rows | ForEach-Object {
            [ordered]@{ id = $_.Id; status = $_.Status; detail = $_.Detail }
        })
        $jsonPath = $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($env:CCDOCTOR_JSON)
        [IO.File]::WriteAllText($jsonPath, (ConvertTo-Json -InputObject $jsonRows))
    }

    $messages.header
    foreach ($row in ($rows | Sort-Object @{ Expression = { $_.Status -ne 'REPRODUCED' } }, Id)) {
        $label = $messages.statuses.($row.Status)
        $line = '{0}  {1}  {2}  |  {3}{4}/{0}.html' -f $row.Id, $label, $row.Title, $baseUrl, $lang
        if ($null -ne $row.Detail) { $line += '  |  ' + $row.Detail }
        $line
    }
    if ($skippedClaude) { $messages.skipped_claude -f $skippedClaude, "$baseUrl$lang/index.html" }
    if ($skippedSlow) { $messages.skipped_slow }
    $messages.summary -f $rows.Count, $reproduced
}
